do $$declare s text;begin s:=pg_get_functiondef('prospecting.personalization_api(text,jsonb)'::regprocedure);s:=replace(s,$old$if d->>'status'='approved' and(v.qa_status$old$,$new$if d->>'status'='approved' and (v.research->>'offer_profile_id' is distinct from 'idd-ava-phone-demo-v1' or v.research->>'service' is distinct from 'AI phone receptionists') then raise exception 'Review the current verified phone-receptionist offer before approval';end if; if d->>'status'='approved' and(v.qa_status$new$);s:=replace(s,$old$v.qa_status='approved_for_review' and v.human_status='approved'$old$,$new$v.qa_status='approved_for_review' and v.human_status='approved' and v.research->>'offer_profile_id'='idd-ava-phone-demo-v1' and v.research->>'service'='AI phone receptionists' and jsonb_typeof(v.research->'capability_ids')='array' and jsonb_array_length(v.research->'capability_ids')>0 and v.research->'capability_ids' <@ '["inbound_answering","business_conversation","caller_questions","demo_roleplay"]'::jsonb$new$);execute s;end$$;
